// registerBackwardCompatibilityRoutes registers redirects for old API paths
func (ar *APIRouter) registerBackwardCompatibilityRoutes(r *mux.Router) {
	// Redirect old /api/dve-nodes/ to /api/v1/dve/nodes/
	r.PathPrefix("/api/dve-nodes/").HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		newPath := "/api/v1/dve/nodes/" + path[len("/api/dve-nodes/"):]
		http.Redirect(w, r, newPath, http.StatusMovedPermanently)
	})

	// Redirect old /api/dve/ to /api/v1/dve/
	r.PathPrefix("/api/dve/").HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		newPath := "/api/v1/dve/" + path[len("/api/dve/"):]
		http.Redirect(w, r, newPath, http.StatusMovedPermanently)
	})

	// Redirect old /api/plugin-management/ to /api/v1/plugin/
	r.PathPrefix("/api/plugin-management/").HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		newPath := "/api/v1/plugin/" + path[len("/api/plugin-management/"):]
		http.Redirect(w, r, newPath, http.StatusMovedPermanently)
	})

	// Redirect old /api/payments/ to /api/v1/payments/
	r.PathPrefix("/api/payments/").HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		newPath := "/api/v1/payments/" + path[len("/api/payments/"):]
		http.Redirect(w, r, newPath, http.StatusMovedPermanently)
	})

	// Redirect old /api/knirvshell/ to /api/v1/shell/
	r.PathPrefix("/api/knirvshell/").HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		newPath := "/api/v1/shell/" + path[len("/api/knirvshell/"):]
		http.Redirect(w, r, newPath, http.StatusTemporaryRedirect)
	})

		"running":   true,
		"timestamp": getCurrentTimestamp(),
	})
}

// RegisterRoutes registers the DVE routes with the router
func (h *DVEHandlers) RegisterRoutes(r *mux.Router, authMiddleware *middleware.AuthMiddleware) {
	// Create a subrouter for DVE endpoints
	dveRouter := r.PathPrefix("/api/dve-nodes").Subrouter()

	// Routes with optional auth (for role-based filtering)
	if authMiddleware != nil {
		optionalAuthRouter := dveRouter.PathPrefix("").Subrouter()
		optionalAuthRouter.Use(authMiddleware.OptionalAuth)
		optionalAuthRouter.HandleFunc("", h.GetDVENodes).Methods("GET", "OPTIONS")
		optionalAuthRouter.HandleFunc("/{id}", h.GetDVENode).Methods("GET", "OPTIONS")
		optionalAuthRouter.HandleFunc("/{id}/endpoints", h.GetDVENodeEndpoints).Methods("GET", "OPTIONS")
		optionalAuthRouter.HandleFunc("/{id}/ssh-endpoint", h.GetDVENodeSSHEndpoint).Methods("GET", "OPTIONS")
		optionalAuthRouter.HandleFunc("/{id}/validation-endpoint", h.GetDVENodeValidationEndpoint).Methods("GET", "OPTIONS")
		optionalAuthRouter.HandleFunc("/{id}/error-resolution-endpoint", h.GetDVENodeErrorResolutionEndpoint).Methods("GET", "OPTIONS")
	} else {
		// If no auth middleware, allow public access
		dveRouter.HandleFunc("", h.GetDVENodes).Methods("GET", "OPTIONS")
		dveRouter.HandleFunc("/{id}", h.GetDVENode).Methods("GET", "OPTIONS")
		dveRouter.HandleFunc("/{id}/endpoints", h.GetDVENodeEndpoints).Methods("GET", "OPTIONS")
		dveRouter.HandleFunc("/{id}/ssh-endpoint", h.GetDVENodeSSHEndpoint).Methods("GET", "OPTIONS")
		dveRouter.HandleFunc("/{id}/validation-endpoint", h.GetDVENodeValidationEndpoint).Methods("GET", "OPTIONS")
		dveRouter.HandleFunc("/{id}/error-resolution-endpoint", h.GetDVENodeErrorResolutionEndpoint).Methods("GET", "OPTIONS")
	}

	// Protected routes for management
	if authMiddleware != nil {
		protectedDVERouter := dveRouter.PathPrefix("").Subrouter()
		protectedDVERouter.Use(authMiddleware.RequireAuth)
		protectedDVERouter.HandleFunc("", h.PostDVENodes).Methods("POST", "OPTIONS")
		protectedDVERouter.HandleFunc("/{id}", h.UpdateDVENode).Methods("PUT", "OPTIONS")
		protectedDVERouter.HandleFunc("/{id}", h.DeleteDVENode).Methods("DELETE", "OPTIONS")
	} else {
		// If no auth middleware, allow all routes (for testnet mode)
		dveRouter.HandleFunc("", h.PostDVENodes).Methods("POST", "OPTIONS")
		dveRouter.HandleFunc("/{id}", h.UpdateDVENode).Methods("PUT", "OPTIONS")
		dveRouter.HandleFunc("/{id}", h.DeleteDVENode).Methods("DELETE", "OPTIONS")
	}

	// /api/dve/ aliases — frontend monitor-panel and connections-panel use these paths
	dveAliasRouter := r.PathPrefix("/api/dve").Subrouter()
	dveAliasRouter.HandleFunc("/workers", h.GetDVEWorkers).Methods("GET", "OPTIONS")
	dveAliasRouter.HandleFunc("/{nodeId}/tasks", h.GetDVENodeTasksAlias).Methods("GET", "OPTIONS")
	dveAliasRouter.HandleFunc("/{nodeId}/metrics", h.GetDVENodeMetricsAlias).Methods("GET", "OPTIONS")

	managerNodeID := creation.DVENodeID
	creation.SSHPublicKey = container.Spec.SSHPublicKey
	creation.SSHPrivateKey = container.SSHKeys.PrivateKey
	creation.SSHPort = container.Endpoints.SSHPort
	creation.IPAddress = "localhost"
	creation.ValidationPort = container.Endpoints.ValidationPort
	creation.ErrorResPort = container.Endpoints.ErrorResPort

	// 3. Update the DVE node in the manager with container details so
	// SSH/IP info is available for Access.  If no manager node was registered
	// yet (no dveManager at creation time) fall back to registering now.
	if dcs.dveManager != nil {
		if managerNodeID != "" {
			updates := map[string]interface{}{
				"ip_address": creation.IPAddress,
				"ssh_port":   creation.SSHPort,
				"public_key": creation.SSHPublicKey,
				"status":     "online",
			}
			if _, err := dcs.dveManager.UpdateNode(managerNodeID, updates); err != nil {
				log.Printf("[DVE Creation] Warning: Failed to update DVE node details: %v", err)
			} else {
				log.Printf("[DVE Creation] Updated DVE node %s with container details", managerNodeID)
			}
		} else {
			// Fallback: manager not wired at creation time — register now with full details
			nodeReq := &objects.RegisterNodeRequest{
				Name:         creation.Name,
				TEEType:      creation.TEEType,
				StakeAmount:  creation.StakeAmount,
				Location:     "local-dve",
				IPAddress:    creation.IPAddress,
				SSHPort:      creation.SSHPort,
				PublicKey:    creation.SSHPublicKey,
				Capabilities: creation.Capabilities,
			}
			if node, err := dcs.dveManager.RegisterNode(nodeReq); err != nil {
				log.Printf("[DVE Creation] Warning: Failed to register DVE node in tracker: %v", err)
			} else {
				creation.DVENodeID = node.ID
				log.Printf("[DVE Creation] Registered DVE node %s (fallback)", node.ID)
			}
		}
	}

	// 4. Auto-start KNIRVAGENT supervisor
	if dcs.knirvagentManager != nil {
		agentDVEID := creation.DVENodeID
		startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		if err := dcs.knirvagentManager.StartAgent(startCtx, agentDVEID, 30*time.Second); err != nil {
			log.Printf("[DVE Creation] Warning: Failed to start KNIRVAGENT supervisor for DVE %s: %v", agentDVEID, err)
		} else {
			creation.SupervisorAgentID = agentDVEID
			log.Printf("[DVE Creation] KNIRVAGENT supervisor started for DVE %s (node %s)", creation.Name, agentDVEID)
		}
	}
}

// 5. Establish chain session (best-effort)
chainSession, err := dcs.establishChainSession(creation)
if err != nil {
	log.Printf("[DVE Creation] Warning: Failed to establish chain session: %v", err)
}

// 6. Create DVE session
session := &objects.DVESession{
	ID:             uuid.New().String(),
	DVECreationID:  creation.ID,
	DVENodeID:      creation.DVENodeID,
	OwnerID:        creation.OwnerID,
	SessionKey:     generateSessionKey(),
	SessionKeyID:   creation.SessionKeyID,
	TEEBinding:     req.TEEAttestation,
	ChainSessionID: "",
	Status:         "pending",
	CreatedAt:      time.Now(),
	ExpiresAt:      time.Now().Add(30 * time.Minute),
}

if chainSession != nil {
	session.ChainSessionID = chainSession.SessionID
	session.Status = "active"
	session.ExpiresAt = chainSession.ExpiresAt
