func (dm *DVEManager) UpdateNode(nodeID string, updates map[string]interface{}) (*objects.DVENode, error) {
	dm.mu.Lock()
	defer dm.mu.Unlock()

	// Get existing node from database
	node, err := dm.getNodeFromDB(nodeID)
	if err != nil {
		return nil, fmt.Errorf("node not found: %w", err)
	}

