								break
							}
						}
						if !found {
							userCreations = append(userCreations, &creation)
						}
					}
				}
			}
			return true
		})
	})

	if err != nil {
		return nil, fmt.Errorf("failed to query user DVE creations: %w", err)
	}

	return userCreations, nil
}

